//! Deterministic trigonometry on 16-bit angles, ported from the decomp.
//!
//! The sine/cosine tables are copied verbatim from the decomp's
//! `include/trig_tables.inc.c` (see `crate::trig_tables`, generated by
//! `tools/gen_trig_tables.py`) — no interpolation, so angles are quantised
//! to 16-unit steps exactly like the decomp
//! (decomp: src/engine/math_util.h:24-28).
//!
//! Argument semantics follow the decomp: `atan2s(y, x)` measures the angle
//! from the +y axis toward +x, i.e. it equals the mathematical
//! `atan2(x, y)` (verified by running: `atan2s(30,40)=9672`).

use crate::angles::Angle;
use crate::trig_tables::{ARCTAN_TABLE, SINE_TABLE};

/// Sine of an angle: `gSineTable[(u16)(x) >> 4]`.
/// decomp: src/engine/math_util.h:27
#[inline]
pub fn sins(angle: Angle) -> f32 {
    SINE_TABLE[((angle.0 as u16) >> 4) as usize]
}

/// Cosine of an angle: `gCosineTable[(u16)(x) >> 4]`, where the decomp's
/// AVOID_UB build defines `gCosineTable` as `gSineTable + 0x400`.
/// decomp: src/engine/math_util.h:24-28
#[inline]
pub fn coss(angle: Angle) -> f32 {
    SINE_TABLE[0x400 + (((angle.0 as u16) >> 4) as usize)]
}

/// Helper for `atan2s`: looks up the arctangent of `y / x`, assuming the
/// resulting angle is in range `[0, 0x2000]` (1/8 of a circle).
/// decomp: src/engine/math_util.c:698
fn atan2_lookup(y: f32, x: f32) -> u16 {
    let ret: u16;
    if x == 0.0 {
        ret = ARCTAN_TABLE[0] as u16;
    } else {
        // C: gArctanTable[(s32)(y / x * 1024 + 0.5f)] — float→int truncation.
        ret = ARCTAN_TABLE[((y / x * 1024.0 + 0.5) as i32) as usize] as u16;
    }
    ret
}

/// Compute the angle from (0, 0) to (x, y) as an [`Angle`]. Given that
/// terrain is in the xz-plane, this is commonly called with (z, x) to get
/// a yaw angle. Note the argument order is the opposite of the usual
/// mathematical convention: `atan2s(y, x)` == math `atan2(x, y)`.
/// decomp: src/engine/math_util.c:713
pub fn atan2s(y: f32, x: f32) -> Angle {
    let ret: u16;
    if x >= 0.0 {
        if y >= 0.0 {
            if y >= x {
                ret = atan2_lookup(x, y);
            } else {
                ret = 0x4000 - atan2_lookup(y, x);
            }
        } else {
            let y = -y;
            if y < x {
                ret = 0x4000 + atan2_lookup(y, x);
            } else {
                ret = 0x8000 - atan2_lookup(x, y);
            }
        }
    } else {
        let x = -x;
        if y < 0.0 {
            let y = -y;
            if y >= x {
                ret = 0x8000 + atan2_lookup(x, y);
            } else {
                ret = 0xC000 - atan2_lookup(y, x);
            }
        } else if y < x {
            ret = 0xC000 + atan2_lookup(y, x);
        } else {
            ret = 0u16.wrapping_sub(atan2_lookup(x, y));
        }
    }
    Angle(ret as i16)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cardinal_values() {
        // Exact table values, no interpolation (decomp tables).
        assert_eq!(sins(Angle::ZERO), 0.0);
        assert_eq!(sins(Angle::QUARTER_TURN), 1.0);
        assert_eq!(sins(Angle::HALF_TURN), 0.0);
        assert_eq!(coss(Angle::ZERO), 1.0);
        assert_eq!(coss(Angle::QUARTER_TURN), 0.0);
        // 16-unit quantisation: sins ignores the low 4 bits.
        assert_eq!(sins(Angle(15)), sins(Angle(0)));
        assert_eq!(sins(Angle(16)), SINE_TABLE[1]);
    }

    #[test]
    fn atan2s_matches_decomp_spot_checks() {
        // Values verified by running the decomp natively (plan §2.3).
        assert_eq!(atan2s(1.0, 0.0).0, 0);
        assert_eq!(atan2s(0.0, 1.0).0, 16384);
        assert_eq!(atan2s(-64.0, 0.0).0, -32768);
        assert_eq!(atan2s(0.0, 64.0).0, 16384);
        assert_eq!(atan2s(0.0, 0.0).0, 0);
        assert_eq!(atan2s(30.0, 40.0).0, 9672);
    }

    #[test]
    fn atan2s_yaw_convention() {
        // atan2s(z, x) is the yaw whose forward is +x/+z: decomp calls it
        // with (z, x) to get a yaw angle.
        assert_eq!(atan2s(0.0, 1.0), Angle::QUARTER_TURN); // +x -> 90°
        assert_eq!(atan2s(1.0, 0.0), Angle::ZERO); // +z -> 0°
        assert_eq!(atan2s(0.0, -1.0), Angle(-16384)); // -x -> -90°
    }

    /// Re-validate the checked-in tables against the decomp source whenever
    /// the checkout is present (oracle/sm64/ is git-ignored, so this skips
    /// in environments without it).
    #[test]
    fn tables_match_decomp_source() {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../oracle/sm64/include/trig_tables.inc.c"
        );
        let src = match std::fs::read_to_string(path) {
            Ok(s) => s,
            Err(_) => return, // no checkout: spot-checks above still guard
        };
        // Parse the flat gSineTable initializer the same way
        // tools/gen_trig_tables.py does (AVOID_UB layout).
        let body = src
            .split("f32 gSineTable[] = {")
            .nth(1)
            .expect("gSineTable")
            .split("s16 gArctanTable")
            .next()
            .expect("arctan boundary");
        let mut vals: Vec<f32> = Vec::new();
        for line in body.lines() {
            let line = line.trim();
            if line.starts_with('#') || line == "};" || line == "f32 gCosineTable[0x1000] = {" {
                continue;
            }
            for tok in line.split(|c: char| c == ',' || c.is_whitespace()) {
                let tok = tok.trim().trim_end_matches(['f', 'F']);
                if tok.is_empty() || tok.starts_with("//") {
                    continue;
                }
                // Skip comment words ("cosine", "negative", "sine").
                if let Ok(v) = tok.parse::<f32>() {
                    vals.push(v);
                }
            }
        }
        assert_eq!(vals.len(), SINE_TABLE.len(), "sin/cos table length");
        for (i, (&a, &b)) in vals.iter().zip(SINE_TABLE.iter()).enumerate() {
            assert_eq!(
                a.to_bits(),
                b.to_bits(),
                "SINE_TABLE[{i}] differs from decomp source"
            );
        }
        let abody = src
            .split("s16 gArctanTable[0x401] = {")
            .nth(1)
            .expect("gArctanTable")
            .split("};")
            .next()
            .expect("arctan end");
        let mut avals: Vec<i16> = Vec::new();
        for tok in abody.split(|c: char| c == ',' || c.is_whitespace()) {
            let tok = tok.trim();
            if tok.is_empty() {
                continue;
            }
            avals.push(i16::from_str_radix(tok.trim_start_matches("0x"), 16).expect("hex"));
        }
        assert_eq!(avals.len(), ARCTAN_TABLE.len(), "arctan table length");
        assert_eq!(avals, ARCTAN_TABLE, "ARCTAN_TABLE differs from decomp source");
    }
}
